        }
      },
      "AResponseThing": {
        "type": "object",
        "properties": {
          "life": {
            "type": "string",
            "description": "Just a description",
            "required": false
          },
          "details": {
            "description": "This gets advanced",
            "required": false,
            "items": {
              "$ref": "#/components/schemas/AResponseSubThing"
            },
            "type": "array"
          }
        }
      },
      "AResponseSubThing": {
        "type": "object",
        "properties": {
          "id": {
            "type": "integer",
            "format": "int64",
            "description": "Just a description",
            "required": false
          },
          "value": {
            "type": "string",
            "description": "More descriptions",
            "required": false
          }
        }
      }
    }
